import {open,readFile} from 'node:fs/promises';
import {parseJourneyInput} from '../tools/staging/check-hosted-journey';
import {runM72Journey} from '../tools/staging/check-m72-hosted';
import {runM78Continuation4ReadonlyRecovery,verifyM78ReadonlyRecoveryPreAuth,M78_READONLY_RECOVERY_PATHS as paths,M78_READONLY_RECOVERY_LOCK as lockPath,M78_READONLY_RECOVERY_AUTH as AUTH,type RecoveryAdmission,type RecoveryRole} from '../tools/staging/check-m78-continuation4-readonly-recovery';
import {m78CanonicalJson as canonical} from '../packages/neuvetra-database/src/m78-validation';
const check:(v:unknown)=>asserts v=v=>{if(!v)throw Error('Recovery entry refused')};
const sha=(b:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(b).digest('hex');
const gatePath='.superpowers/m78-readonly-recovery-execution-admission.json';
const evidencePaths={mainText:'.superpowers/m78-hosted-continuation4.jsonl',diagnosticText:'.superpowers/m78-hosted-continuation4-diagnostics.jsonl',baselineResultText:'evaluations/research-qa/m78-continuation4-baseline-independent-result.json',exerciseGateText:'.superpowers/m78-continuation4-exercise-gate.json',providerObservationText:'evaluations/research-qa/m78-continuation4-failure-http-observation.json',browserObservationText:'evaluations/research-qa/m78-continuation4-browser-http-observation.json',failureReviewText:'evaluations/research-qa/m78-continuation4-exercise-failure-qa-result.json'};
const io={read:async(p:string)=>{try{return await readFile(p,'utf8')}catch(e){if((e as NodeJS.ErrnoException).code==='ENOENT')return null;throw e}},append:async(p:string,text:string,exclusive:boolean)=>{check(Object.values(paths).includes(p as any));const f=await open(p,exclusive?'wx':'a',0o600);try{await f.writeFile(text);await f.sync()}finally{await f.close()}}};
let lock:Awaited<ReturnType<typeof open>>|undefined;
try{
 const stdin=await Bun.stdin.text();check(stdin.length<=128000);const raw=JSON.parse(stdin),input=parseJourneyInput(raw);
 const gateText=await readFile(gatePath,'utf8');check(sha(gateText)===raw.recoveryAdmissionSha256);const gate=JSON.parse(gateText);
 check(gate.status==='m78_readonly_recovery_execution_admitted'&&gate.applicationPostRequests===0&&gate.workspaceId===input.roster.workspaceId);
 for(const p of gate.pins)check(sha(await readFile(p.path))===p.sha256);
 check(gate.pins.some((p:any)=>p.path==='.superpowers/m78-readonly-recovery-entry.ts'));
 const runtime=JSON.parse(await readFile(gate.runtime.path,'utf8'));check(sha(await readFile(gate.runtime.path))===gate.runtime.sha256&&runtime.status==='m78_get_route_deployed_runtime_verified'&&runtime.commit===gate.runtimeCommit&&runtime.ready.schemaVersion===21);
 const age=Date.now()-Date.parse(runtime.observedAt);check(age>=0&&age<15*60*1000);
 const sourceText=await readFile(gate.sourceGate.path,'utf8');check(sha(sourceText)===gate.sourceGate.sha256);const source=JSON.parse(sourceText);
 check(source.runtime.commit===runtime.commit&&source.runtime.deploymentId===runtime.deploymentId);
 const loaded=Object.fromEntries(await Promise.all(Object.entries(evidencePaths).map(async([k,p])=>[k,await readFile(p,'utf8')])));
 const admission={...loaded,currentSourceGateText:sourceText,currentSourcePins:source.sourcePins,load:async(p:string)=>new Uint8Array(await readFile(p))} as RecoveryAdmission;
 await verifyM78ReadonlyRecoveryPreAuth(admission);
 const expectedSubjects=Object.fromEntries(input.accounts.map(a=>[a.role,a.id])) as Record<RecoveryRole,string>;
 check(canonical(expectedSubjects)===canonical(gate.expectedSubjects));
 for(const p of Object.values(paths))check(await io.read(p)===null);
 lock=await open(lockPath,'wx',0o600);await lock.writeFile('{"profile":"m78-readonly-recovery-exclusive-v1"}\n');await lock.sync();
 const result=await runM78Continuation4ReadonlyRecovery({admission,expectedSubjects,io,fetch:globalThis.fetch,auth:{
  open:async(role,request)=>{const account=input.accounts.find(a=>a.role===role)!;const response=await request(AUTH+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:input.env.SUPABASE_ANON_KEY,'content-type':'application/json'},body:JSON.stringify({email:account.email,password:account.password})});const body=await response.json() as any;check(typeof body.access_token==='string'&&body.access_token.length>0&&body.access_token.length<=8192);return{role,subject:body.user?.id??'',authorization:'Bearer '+body.access_token,status:response.status as 200}},
  close:async(session,request)=>{const r=await request(AUTH+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:input.env.SUPABASE_ANON_KEY,authorization:session.authorization}});await r.body?.cancel();return r.status},
 },readLegacy:async(request,expected)=>{
  let captured:any=null;
  const result=await runM72Journey({...input,mode:'baseline'},{load:async()=>null,save:async value=>{captured=value},fetch:(async(url:any,init?:RequestInit)=>{const r=await request(String(url),init??{});if(String(url)==='https://www.neuvetra.ai/ready'){const body=await r.json() as any;check(r.status===200&&body.status==='ready'&&body.schemaVersion===21&&body.legacyContainmentVerified===true);return Response.json({...body,schemaVersion:14},{status:r.status,headers:r.headers})}return r}) as typeof fetch});
  check(result.status==='passed'&&result.applicationPostRequests===0&&result.allCreatedAuthSessionsClosed===true&&canonical(captured?.baseline)===canonical(expected));
  return{value:captured.baseline,applicationPostRequests:0,allCreatedAuthSessionsClosed:true};
 }});
 console.log(JSON.stringify({status:result.status,requests:result.requests,applicationPostRequests:result.applicationPostRequests,allCreatedAuthSessionsClosed:result.allCreatedAuthSessionsClosed,unknownAuthSessions:result.unknownAuthSessions}));if(result.status!=='passed')process.exitCode=1;
}catch{console.log(JSON.stringify({status:'failed',stage:'readonly_recovery_entry',successNotInferred:true}));process.exitCode=1}
finally{if(lock)await lock.close();/* Keep the lock as a durable no-replay marker. */}

param([Parameter(Mandatory=$true)][ValidatePattern('^[a-f0-9]{64}$')][string]$AdmissionSha256)
$ErrorActionPreference='Stop'
try {
 $workspace=[IO.Path]::GetFullPath('C:/Users/nimab/.codex/worktrees/4441/Neuvetra')
 function Read-Pinned($pin) {
  if($pin.sha256 -cnotmatch '^[a-f0-9]{64}$'){throw 'invalid pin'}
  $resolved=[IO.Path]::GetFullPath((Join-Path $workspace $pin.path))
  if(-not $resolved.StartsWith($workspace+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'outside workspace'}
  if((Get-FileHash -LiteralPath $resolved -Algorithm SHA256).Hash.ToLowerInvariant() -cne $pin.sha256){throw 'changed pin'}
  return [IO.File]::ReadAllText($resolved)
 }
 $gate=Read-Pinned @{path='.superpowers/m78-readonly-recovery-execution-admission.json';sha256=$AdmissionSha256} | ConvertFrom-Json
 if($gate.status -cne 'm78_readonly_recovery_execution_admitted' -or $gate.applicationPostRequests -ne 0 -or $gate.workspaceId -cne '8b90c706-1710-494d-b12d-02eef88eacb7'){throw 'wrong gate'}
 $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
 foreach($pin in $gate.pins){if(-not $seen.Add($pin.path)){throw 'duplicate pin'};$null=Read-Pinned $pin}
 foreach($required in @('.superpowers/m78-private-readonly-recovery.ps1','.superpowers/m78-readonly-recovery-entry.ts','tools/staging/check-m78-continuation4-readonly-recovery.ts')){if(-not $seen.Contains($required)){throw 'required source missing'}}
 $runtime=Read-Pinned $gate.runtime | ConvertFrom-Json
 if($runtime.status -cne 'm78_get_route_deployed_runtime_verified' -or $runtime.commit -cne $gate.runtimeCommit -or $runtime.ready.schemaVersion -ne 21 -or $runtime.autodeploy -ne $false){throw 'wrong runtime'}
 $age=[DateTimeOffset]::UtcNow-[DateTimeOffset]::Parse($runtime.observedAt)
 if($age.TotalSeconds -lt 0 -or $age.TotalMinutes -ge 15){throw 'stale runtime'}
 $source=Read-Pinned $gate.sourceGate | ConvertFrom-Json
 if($source.status -cne 'm78_continuation4_readonly_recovery_source_admitted' -or $source.sourcePins.Count -lt 173 -or $source.runtime.commit -cne $runtime.commit -or $source.runtime.deploymentId -cne $runtime.deploymentId){throw 'wrong source gate'}
 foreach($pin in $source.sourcePins){$null=Read-Pinned $pin}
 foreach($name in @('m78-continuation4-readonly-recovery.jsonl','m78-continuation4-readonly-recovery-diagnostics.jsonl','m78-continuation4-readonly-recovery-observation.json','m78-continuation4-readonly-recovery.jsonl.lock')){if(Test-Path -LiteralPath (Join-Path $workspace ('.superpowers/'+$name))){throw 'execution exists'}}
 Add-Type -AssemblyName System.Security
 $clearBytes=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes('C:/Users/nimab/Neuvetra/m63-runtime/recovery/m63-private-config.json.dpapi'),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
 $data=[Text.Encoding]::UTF8.GetString($clearBytes) | ConvertFrom-Json
 [Array]::Clear($clearBytes,0,$clearBytes.Length)
 $data | Add-Member -NotePropertyName recoveryAdmissionSha256 -NotePropertyValue $AdmissionSha256 -Force
 $start=[Diagnostics.ProcessStartInfo]::new();$start.FileName='C:/Users/nimab/.bun/bin/bun.exe';$start.WorkingDirectory=$workspace
 $start.ArgumentList.Add('run');$start.ArgumentList.Add((Join-Path $workspace '.superpowers/m78-readonly-recovery-entry.ts'))
 $start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
 $process=[Diagnostics.Process]::Start($start);$process.StandardInput.Write(($data | ConvertTo-Json -Depth 20 -Compress));$process.StandardInput.Close();$data=$null
 $output=$process.StandardOutput.ReadToEndAsync();$errors=$process.StandardError.ReadToEndAsync();$process.WaitForExit()
 Write-Output $output.Result
 if($process.ExitCode -ne 0){Write-Output 'Read-only recovery failed; sensitive diagnostics withheld.';exit 1}
}catch{Write-Output 'Read-only recovery unavailable; sensitive diagnostics withheld.';exit 1}
